   \frac{\overrightarrow y \,.\,}{rightarrow x } & \frac{\overrightarrow y \,.\,}{rightarrow y } & \frac{\overrightarrow y \,.\,}{rightarrow z }  \cr 
   \frac{\overrightarrow z \,.\,}{rightarrow x } & \frac{\overrightarrow z \,.\,}{rightarrow y } & \frac{\overrightarrow z \,.\,}{rightarrow z }  \cr 

 } } \right| 

Volume of the parallelopiped  v = \left[ {\matrix{ {\widehat a} & {\widehat b} & {\widehat c}  \cr

} } \right] 

$\therefore ${v^2} = {\left[ {\matrix{ {\widehat a} & {\widehat b} & {\widehat c}  \cr

 } } \right]^2} = \left| {\matrix{
   {\widehat a\,.\,\widehat a} & {\widehat a\,.\,\widehat b} & {\widehat a\,.\,\widehat c}  \cr 
   {\widehat b\,.\,\widehat a} & {\widehat b\,.\,\widehat b} & {\widehat b\,.\,\widehat c}  \cr 
   {\widehat c\,.\,\widehat a} & {\widehat c\,.\,\widehat b} & {\widehat c\,.\,\widehat c}  \cr 

 } } \right| 


 = \left| {\matrix{
   1 & {\frac{1}{2}} & {\frac{1}{2}}  \cr 
   {\frac{1}{2}} & 1 & {\frac{1}{2}}  \cr 
   {\frac{1}{2}} & {\frac{1}{2}} & 1  \cr 

 } } \right| = \frac{1}{2}  (on evaluation)

 \Rightarrow v = \left[ {\matrix{ {\widehat a} & {\widehat b} & {\widehat c}  \cr

} } \right] = {1 \over {\sqrt 2 }}
